{
  "business/receipts": {
    "domain": "business",
    "tags": ["receipt", "financial", "expense"],
    "topics": ["expense-tracking", "bookkeeping"],
    "allowed_extensions": [".jpg", ".jpeg", ".png", ".pdf", ".txt", ".json"],
    "filename_rules": {
      "token_delimiters": ["__"],
      "case": "preserve",
      "patterns": [
        {
          "name": "date",
          "regex": "^\\d{4}-\\d{2}-\\d{2}"
        },
        {
          "name": "vendor",
          "regex": "(?<=^\\d{4}-\\d{2}-\\d{2}__)[A-Za-z0-9]+"
        },
        {
          "name": "descriptor",
          "regex": "(?<=__)[A-Za-z0-9]+$"
        }
      ]
    }
  },
  "cnc/design": {
    "domain": "cnc",
    "tags": ["cnc", "design"],
    "topics": ["cnc"],
    "allowed_extensions": [".png", ".svg", ".json"],
    "filename_rules": {
      "token_delimiters": ["_", "-", " "],
      "case": "lower",
      "patterns": [
        {
          "name": "task_id",
          "regex": "(MFG|CNC)-\\d+"
        }
      ]
    }

